    def valid_date(self,value):
        try: datetime.strptime(value.strip(),'%Y-%m-%d'); return True
        except (ValueError,AttributeError): return False
    def available_dates(self):
        conn=self.db(); rows=conn.execute("SELECT DISTINCT visit_date FROM visits WHERE TRIM(visit_date)<>'' ORDER BY visit_date DESC").fetchall(); conn.close(); return [r[0] for r in rows]
    def customer_choices(self):
        conn=self.db(); rows=conn.execute('SELECT id,name FROM customers ORDER BY name').fetchall(); conn.close(); return [f'{r[0]} - {r[1]}' for r in rows]
    def customer_id_from_choice(self,value):
        try: return int(value.split(' - ',1)[0])
        except Exception: return None

    def resolve_customer_id(self, value):
        """Resolve an existing customer or ask before creating a name-only customer."""
        value=(value or '').strip()
        if not value:
            return None
        cid=self.customer_id_from_choice(value)
        if cid:
            conn=self.db()
            exists=conn.execute('SELECT 1 FROM customers WHERE id=?',(cid,)).fetchone()
            conn.close()
            return cid if exists else None
        conn=self.db()
        row=conn.execute('SELECT id FROM customers WHERE LOWER(TRIM(name))=LOWER(TRIM(?)) ORDER BY id LIMIT 1',(value,)).fetchone()
        conn.close()
        if row:
            return row[0]
        if not messagebox.askyesno('Customer Not Found', f'No customer named “{value}” was found. Create a customer record with this name only? You can add the vehicle and contact details later.'):
            return None
        now=datetime.now().strftime('%Y-%m-%d %H:%M')
        conn=self.db()
        cur=conn.cursor()
        cur.execute('INSERT INTO customers(name,plate,model,address,technician,created_at) VALUES(?,?,?,?,?,?)',(value,'','','','',now))
        cid=cur.lastrowid
        conn.commit()
        conn.close()
        return cid

